private void btnHesapla_Click(object sender, EventArgs e)
{
    // Sabit Birim Fiyatlar
    int cayFiyat = 10;
    int tostFiyat = 60;
    int suFiyat = 10;

    // Sipariş Adetleri (Örnek başlangıç)
    int cayAdet = 4;
    int tostAdet = 2;
    int suAdet = 3;
    int kisiSayisi = 3;

    // Hesaplama
    int toplamTutar = (cayAdet * cayFiyat) + (tostAdet * tostFiyat) + (suAdet * suFiyat);
    double kisiBasiPay = (double)toplamTutar / kisiSayisi;

    // Ekrana Formatlı Basma
    lblToplamTutar.Text = "Toplam Tutar: " + toplamTutar.ToString() + " TL";
    lblKisiBasiPay.Text = "Kişi Başı Pay: " + kisiBasiPay.ToString("0.00") + " TL";
}
